 '.fpe-lab{max-width:100%;min-width:0;color:var(--fg)}.fpe-lab *{box-sizing:border-box}.fpe-lab [hidden]{display:none!important}',
 '.fpe-note,.fpe-feedback{font-size:13px;line-height:1.7;color:var(--fg-soft)}.fpe-presets,.fpe-choices,.fpe-actions{display:flex;flex-wrap:wrap;gap:8px}',
 '.fpe-lab button{min-height:44px}.fpe-presets button,.fpe-choices button{flex:1 1 130px}.fpe-control{margin:14px 0;display:grid;gap:6px}',
 '.fpe-control input,.fpe-control select{width:100%;min-height:40px;min-width:0;max-width:100%;margin:0}.fpe-question{margin:14px 0;padding:12px;border-left:3px solid var(--cl-gold);background:var(--bg)}',
 '.fpe-question p{margin:0 0 8px}.fpe-results{margin-top:18px}.fpe-scroll{max-width:100%;overflow-x:auto;border:1px solid var(--border);border-radius:7px;margin:14px 0;-webkit-overflow-scrolling:touch}',
 '.fpe-lab svg{display:block;width:100%;min-width:760px;height:auto;background:var(--bg)}.fpe-lab svg text{font-family:inherit;fill:var(--fg);letter-spacing:0}.fpe-grid{stroke:var(--border);stroke-width:1}',
 '.fpe-lab table{display:table;min-width:760px;width:100%;border-collapse:collapse;white-space:normal;font-size:13px}',
 '.fpe-lab th,.fpe-lab td{padding:10px;text-align:left;border:1px solid var(--border)}.fpe-lab code{overflow-wrap:anywhere;white-space:normal}',
 '.fpe-lab :focus-visible{outline:3px solid var(--cl-focus);outline-offset:2px}',
